package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen1Test {



    @Test
    public void testValue_withValidString() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        // To ensure writeDeferredName() and beforeValue() work correctly, 
        // we should be in an object context or at least not violate state.
        // However, value(String) is often used after name(String).
        // Let's test a simple value assignment.

        writer.beginObject();
        writer.name("testKey");
        JsonWriter result = writer.value("testValue");
        writer.endObject();

        assertEquals("{\"testKey\":\"testValue\"}", out.toString());
        assertSame(writer, result);
    }






}

