package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen1Test {







    @Test
    public void testValue_withSpecialCharacters() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.beginObject();
        writer.name("special");
        writer.value("quote\" and backslash\\");
        writer.endObject();

        // Gson escapes quotes and backslashes automatically via string(value)
        assertEquals("{\"special\":\"quote\\\" and backslash\\\\\"}", out.toString());
    }


}
